  try{const value=await producerSettings.prepareOutput(profileState?{profileId:profileState.selectedProfileId}:{format:document.querySelector('#outputFormat').value});if(operation===broadcastOperation){broadcastState=value;status.textContent='Output opened. Review its picture and browser sources, then return here.';}}
